function removeKept(id){
  store.set(IMPORT_KEY, importedKept().filter(y => y.id !== id));
  const i = D.armies.findIndex(y => y.id === id && y.imported); if(i >= 0) D.armies.splice(i, 1);
  const j = importStale.findIndex(y => y.id === id); if(j >= 0) importStale.splice(j, 1);
  try { localStorage.removeItem('wh-used-' + id); localStorage.removeItem('wh-check-' + id); localStorage.removeItem('wh-res-' + id); } catch(e){}
  if(favIds().includes(id)) setFav(id, false);
}

function resRule(){
  const t = String(D.rules['Strategic Reserves'] || '').replace(/\*\*/g, '');
  const when = /^(Before the battle, in the [A-Z][A-Za-z ]+? step)\b/.exec(t);
  const ex = /\bselect one or more friendly units \(excluding ([A-Z][A-Z /]*[A-Z])\) to place in strategic reserves\b/.exec(t);
  const lim = /(Unless otherwise stated, the combined points value of all of your strategic reserves units [^.]*?cannot exceed (\d+)% of your points limit for your battle size\.)/.exec(t);
  return { when:when ? when[1] : null, excl:ex ? ex[1].split('/').map(k => k.trim().replace(/S$/, '')) : [], quote:lim ? lim[1] : null, pct:lim ? +lim[2] : null };
}

function resGrants(u, name){
  const A = army(), f = factionOf(A), dets = detachmentsOf(A), out = [];
  for(const g of D.grants || []){
    if(g.grants !== name || g.type !== 'ability') continue;
    const p = String(g.rule).split(' · '), rn = p[p.length - 1], has = x => x.abilities.find(ab => ab.name === rn && !naReason(ab) && String(ab.text).includes(g.text) && !resInBattle(ab));
    if(p.length === 2){ if(p[0] === f.name + ' army rule' && f.armyRules.some(r => r.name === rn) && isObj(g.to) && matches(g.to, u)) out.push({ g, how:'unit', src:rn }); continue; }
    if(/ rule$/.test(p[1])){ if(p[0] === f.name && dets.some(d => d.name + ' rule' === p[1] && detRules(d).some(r => r.name === rn)) && isObj(g.to) && matches(g.to, u)) out.push({ g, how:'unit', src:rn }); continue; }
    if(g.pick === 'one'){ const giver = A.units.find(has); if(giver && isObj(g.to) && matches(g.to, u)) out.push({ g, how:'may', src:rn, ab:has(giver), giver:has(giver).who || giver.short || giver.name }); continue; }
    const ab = has(u); if(!ab || !(g.to === 'this unit / model' || (isObj(g.to) && matches(g.to, u)))) continue;
    out.push({ g, how:/\b(?:this|the bearer['’]?s?) unit\b/i.test(g.text) ? 'unit' : 'model', src:rn, ab, who:ab.who || u.short || u.name });
  }
  return out;
}

function resWhile(g, u){
  const w = String(g.while || '').split('; ').filter(x => x && !/^In the Declare Battle Formations step$/i.test(x));
  if(!w.length) return true;
  if(w.length > 1) return null;
  const m = /^If this model is attached to an? ([A-Z][A-Z’' -]*[A-Z]) unit during the Declare Battle Formations step$/.exec(w[0]);
  if(!m) return null;
  if(!u.leads) return false;
  const kws = u.kw.map(k => k.replace(/^Faction: /, '').toUpperCase()), words = m[1].split(' ');
  for(let i = 0; i < words.length;){ let j = words.length; while(j > i && !kws.includes(words.slice(i, j).join(' '))) j--; if(j === i) return false; i = j; }
  return true;
}

function resDeepStrike(u){
  const has = unitRules(u).some(r => ruleKey(r) === 'Deep Strike'), pk = Object.keys(u.partialRules || {}).find(r => ruleKey(r) === 'Deep Strike');
  const own = has && !pk, part = has && pk ? [partialWho(u, pk)] : [], grants = [], may = [], cond = [];
  for(const x of resGrants(u, 'Deep Strike')){
    if(x.how === 'may'){ may.push(x); continue; }
    const w = resWhile(x.g, u); if(w === false) continue;
    if(w === null){ cond.push(x); continue; }
    if(x.how === 'model' && modelCount(u) > 1){ if(!own && !part.includes(x.who)) part.push(x.who); continue; }
    grants.push(x);
  }
  return { own, part, grants, may, cond };
}

function resTotal(){
  const A = army(), R = resRule(), done = resDone();
  const units = A.units.filter(u => !R.excl.some(k => hasKw(u, k)));
  const n = units.reduce((t, u) => t + resBoxes(u).filter(k => done.has(k)).length, 0);
  const pts = units.reduce((t, u) => t + resBoxes(u).filter(k => done.has(k)).length * (u.pts || 0), 0);
  return { n, pts, limit:R.pct != null && A.points ? Math.floor(A.points * R.pct / 100) : null };
}

function resBar(){
  const T = resTotal(), over = T.limit != null && T.pts > T.limit;
  return '<div class="resbar' + (over ? ' over' : '') + '" role="status" aria-live="polite"><span class="lbl">In reserves</span><b class="respts">' + T.pts + (T.limit != null ? ' / ' + T.limit : '') + ' pts</b>' +
    '<span class="resn">' + T.n + (T.n === 1 ? ' unit' : ' units') + (T.limit == null ? '' : over ? ' · <b>' + (T.pts - T.limit) + ' pts over the limit</b>' : ' · ' + (T.limit - T.pts) + ' pts left') + '</span></div>';
}

function screenReserves(){
  const A = army(), R = resRule(), done = resDone();
  const box = (k, label, what, off) => '<button class="tick' + (done.has(k) ? ' on' : '') + '" data-rtick="' + esc(k) + '" aria-pressed="' + done.has(k) + '"' + (off ? ' disabled' : '') +
    ' aria-label="' + esc(what + (label ? ', ' + label : '') + ' in strategic reserves') + '">' + (done.has(k) ? '✓' : '') + '</button>';
  const rows = A.units.map(u => {
    const ex = R.excl.find(k => hasKw(u, k)), ds = resDeepStrike(u), ks = resBoxes(u), c = ks.length;
    const marks = [];
    const DS = linkTo('rule', 'Deep Strike', 'Deep Strike'), q = g => ' <span class="from">“' + esc(String(g.text).replace(/^- /, '').replace(/\*\*/g, '')) + '”</span>';
    const srcLink = x => x.ab ? linkTo('ability', abilityKey(x.ab), x.src) : linkTo('rule', x.src, x.src);
    if(ds.own) marks.push('<span class="tg resds" data-resds="own">' + DS + '</span>');
    for(const m of ds.part) marks.push('<span class="tg m resds" data-resds="part:' + esc(m) + '">' + DS + ': ' + esc(m) + ' only</span>');
    for(const x of ds.grants) marks.push('<span class="tg resds" data-resds="grant:' + esc(x.src) + '">' + DS + ' · ' + srcLink(x) + '</span>' + q(x.g));
    for(const x of ds.may) marks.push('<span class="tg m resds" data-resds="may:' + esc(x.src) + '">can be given ' + DS + ' · ' + srcLink(x) + ' (' + esc(x.giver) + ')</span>' + q(x.g));
    for(const x of ds.cond) marks.push('<span class="tg m resds" data-resds="cond:' + esc(x.src) + '">' + DS + ' if: ' + srcLink(x) + '</span>' + q(x.g));
    if(ex) marks.push('<span class="tg m">' + linkTo('rule', 'Strategic Reserves', ex.toUpperCase() + ': excluded') + '</span>');
    return '<div class="tl resu" data-resu="' + esc(u.id) + '"><span class="ticks">' + ks.map((k, i) => (c > 1 ? '<i>' + (i + 1) + '</i>' : '') + box(k, c > 1 ? 'Unit ' + (i + 1) : '', unitLabel(u), !!ex)).join('') + '</span>' +
      '<span>' + linkTo('unit', u.id, unitLabel(u)) + ' <span class="from">' + u.pts + ' pts' + (c > 1 ? ' each, ×' + c : '') + '</span>' + (marks.length ? '<span class="resm">' + marks.map(m => '<span>' + m + '</span>').join('') + '</span>' : '') + '</span></div>';
  }).join('');
  return '<div class="res">' + resBar() + '<div class="sec-h"><h2>Strategic reserves</h2><button class="textbtn" data-rreset>Reset</button></div>' +
    '<div class="pg">' + (R.when ? '<div class="pgr"><span class="pgk">When</span><span class="pgv">' + esc(R.when) + '</span></div>' : '') +
    '<div class="pgr"><span class="pgk">Limit</span><span class="pgv">' + (R.quote ? esc(R.quote) + ' <span class="from">(' + linkTo('rule', 'Strategic Reserves', 'Strategic Reserves') + ', ' + esc(A.points + ' pts · ' + A.battleSize) + ')</span>'
      : linkTo('rule', 'Strategic Reserves', 'Strategic Reserves')) + '</span></div></div>' +
    '<div class="sec-h"><h2>Your units</h2><span class="c">' + A.units.reduce((t, u) => t + (u.copies || 1), 0) + '</span></div><div class="resl">' + rows + '</div>' +
    '<p class="note">Tick the units you place in strategic reserves; the total counts each ticked unit’s points as the list prints them. Deep Strike: on the unit’s Rules line (every model; “only” where one model alone has it), or given by the rule or ability named, in its words; “can be given”: the ability gives it to one unit you select; “if”: its condition is for you to check. What units are given during the battle, as they go back into reserves, is not listed. Each name opens its rule. The boxes are kept for this list on this phone; Reset clears them.</p></div>';
}

function removeImported(id){
  const a = armyById(id), x = importedKept().find(y => y.id === id), name = (a || x || {}).name || 'the list';
  removeKept(id);
  ONLY = D.armies.length === 1 ? D.armies[0] : null;
  hideSheet(); go({ s:'home' }, 'replace');
  toast('Removed ' + name);
}
